<?php
session_start();if(empty($_SESSION['user_id'])){header('Location: login.html');exit;}
require __DIR__.'/db.php';require __DIR__.'/event-common.php';
$uid=(int)$_SESSION['user_id'];
if(!eventStudent($conn,$uid)){header('Location: admin/events.php');exit;}
$s=$conn->prepare("SELECT e.*, (SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=e.event_id AND r.status IN ('registered','attended')) AS joined, (SELECT r.status FROM event_registrations r WHERE r.event_id=e.event_id AND r.user_id=? LIMIT 1) AS my_status FROM events e WHERE e.status='published' ORDER BY e.starts_at ASC");$s->bind_param('i',$uid);$s->execute();$events=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$message=['joined'=>'Registration confirmed.','cancelled'=>'Registration cancelled.','full'=>'This exhibition is full.','closed'=>'Registration is closed.','error'=>'Could not update registration.'][($_GET['msg']??'')]??'';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exhibitions | MIRA</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')||'light'}catch(e){}</script><link rel="stylesheet" href="event.css"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-student-nav.css?v=2"></head><body class="event-page"><?php require __DIR__ . "/mira-student-nav.php"; ?><main class="event-container"><p class="event-eyebrow">NSBM STUDENT ART & CRAFT</p><h1>Discover exhibitions ✦</h1><p class="event-muted">Explore showcases and register to take part.</p><?php if($message):?><p class="event-alert" role="status"><?=eventEsc($message)?></p><?php endif;?><section class="event-public-grid"><?php foreach($events as $e):$open=strtotime($e['registration_deadline'])>=time()&&strtotime($e['starts_at'])>time()&&(int)$e['joined']<(int)$e['capacity'];$registered=in_array($e['my_status'],['registered','attended'],true);?><article class="event-card"><?php if(!empty($e['poster_path'])):?><a href="exhibition-detail.php?id=<?=(int)$e['event_id']?>"><img class="event-poster" src="<?=eventEsc($e['poster_path'])?>" alt="<?=eventEsc($e['title'])?> poster" loading="lazy"></a><?php endif;?><p class="event-eyebrow"><?=eventEsc(date('M j, Y',strtotime($e['starts_at'])))?></p><h2><?=eventEsc($e['title'])?></h2><p><?=nl2br(eventEsc($e['description']))?></p><p class="event-muted">📍 <?=eventEsc($e['venue'])?></p><p class="event-muted">Starts: <?=eventEsc(date('M j, Y g:i A',strtotime($e['starts_at'])))?></p><p class="event-muted">Registration closes: <?=eventEsc(date('M j, Y g:i A',strtotime($e['registration_deadline'])))?></p><p><?= (int)$e['joined'] ?> / <?= (int)$e['capacity'] ?> registered</p><form method="post" action="register-event.php"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="event_id" value="<?=(int)$e['event_id']?>"><?php if($registered):?><button class="event-outline" name="action" value="cancel" type="submit" onclick="return confirm('Cancel this registration?')">Cancel registration</button><?php elseif($open):?><button class="event-primary" name="action" value="register" type="submit">Register for exhibition</button><?php else:?><p class="event-muted">Registration unavailable</p><?php endif;?></form><a class="event-artlink" href="exhibition-detail.php?id=<?=(int)$e['event_id']?>">View selected artworks →</a> <a class="event-artlink" href="request-exhibition.php?event_id=<?=(int)$e['event_id']?>">Request to exhibit my art →</a></article><?php endforeach;?><?php if(!$events):?><p class="event-card">No published exhibitions yet. Check back soon.</p><?php endif;?></section></main></body></html>
